fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // If prefix is empty, it always matches
    if p.is_empty() {
        return true;
    }
    
    // If sequence is shorter than prefix, it can't match
    if v.len() < p.len() {
        return false;
    }
    
    // Compare character by character
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    let mut result = Vec::new();
    
    for seq in xs {
        if has_prefix(&seq, &p) {
            result.push(seq);
        }
    }
    
    result
}